"use strict";

var utils = require("../../../utils");

module.exports = function (defaultFuncs, api, ctx) {
  return function removeUserFromGroup(userID, threadID, callback) {
    var resolveFunc = function () { };
    var rejectFunc = function () { };
    var returnPromise = new Promise(function (resolve, reject) {
      resolveFunc = resolve;
      rejectFunc = reject;
    });

    if (!callback) {
      callback = function (err, friendList) {
        if (err) {
          return rejectFunc(err);
        }
        resolveFunc(friendList);
      };
    }

    if (!userID || !threadID) {
      var error = {
        error: "removeUserFromGroup: need userID and threadID"
      };
      // Đã thay npmlog bằng console.error
      console.error("removeUserFromGroup", error);
      return callback(error);
    }

    var form = {
      uid: userID,
      tid: threadID
    };

    defaultFuncs
      .post("https://www.facebook.com/chat/remove_participants/", ctx.jar, form)
      .then(utils.parseAndCheckLogin(ctx, defaultFuncs))
      .then(function (resData) {
        if (resData.error) {
          throw resData;
        }
        return callback();
      })
      .catch(function (err) {
        // Đã thay npmlog bằng console.error
        console.error("removeUserFromGroup", err);
        return callback(err);
      });

    return returnPromise;
  };
};